    @Inject private MazeBingoConfig config;
    @Inject private MazeApiClient apiClient;
    @Inject private MazeBingoPanel panel;
    @Inject private ClientToolbar clientToolbar;
    @Inject private ItemManager itemManager;
    @Inject private ChatMessageManager chatMessageManager;
    @Inject private MazeEventNotificationOverlay notifOverlay;
    @Inject private MazeSoundManager soundManager;

    private final List<ActiveTile> activeTiles = new CopyOnWriteArrayList<>();
    private volatile Map<String, String> tileDescriptions = new HashMap<>();
    private volatile Set<Integer> boobyTrapTileIds = new java.util.HashSet<>();
    private volatile int selectedTileId = -1;

    public List<ActiveTile> getActiveTiles() { return activeTiles; }

    // Keyed by Skill.ordinal(). Absence (-1 default) means "not yet seen this session";
    // onStatChanged initializes it on first fire without counting XP.
    private final Map<Integer, Integer> xpSnapshot = new ConcurrentHashMap<>();

    // NPC kill tracking: npcIndex → NPC reference for every NPC the player has hit
    private final Map<Integer, NPC> attackedNpcs = new HashMap<>();

    // npcIndex → game tick a kill was credited on. One kill can surface as an ActorDeath, a
    // dead-flagged NPC on the tick poll, a despawn and an NPC loot drop; this keeps only the
    // first of those. Entries expire so a reused NPC index can still be credited later.
    private final Map<Integer, Integer> creditedKills = new HashMap<>();
    private static final int KILL_CREDIT_TICKS = 10;

    // Dedup: "tileId:itemName" → game tick of last submit; prevents double-counting when
    // both onNpcLootReceived and onLootReceived fire for the same NPC kill
    private final Map<String, Integer> recentSubmits = new HashMap<>();

    private ScheduledExecutorService executor;
    private ScheduledFuture<?> pollTask;
    private ScheduledFuture<?> versionPollTask;
    private volatile String lastKnownVersion = null;
    private NavigationButton navButton;

    private volatile int lastSeenEventId = 0;
    private volatile boolean eventsInitialized = false;

    @Override
    protected void startUp() {
        try {
            soundManager.init(getPluginDirectory());
            soundManager.ensureDownloaded();
        } catch (IOException e) {
            // Sounds are a nicety; everything else about the plugin still works without them.
            log.warn("Could not open the plugin directory; notification sounds are unavailable", e);
        }

        executor = Executors.newSingleThreadScheduledExecutor();
        panel.setOnRefresh(() -> executor.execute(this::refreshMazeState));
        panel.setOnTileClick(tile -> {
            if (selectedTileId == tile.id) {
                selectedTileId = -1;
                panel.hideTileInfo();
                return;
            }
            selectedTileId = tile.id;
            panel.setSelectedTileOnMap(tile.id);
            String desc = tileDescriptions.getOrDefault(String.valueOf(tile.id), "");
            panel.showTileInfoLoading(tile.id, desc);
            String apiUrl = config.apiUrl();
            String team = config.teamName();
            executor.execute(() -> {
                TileProgressResponse resp = apiClient.fetchTileProgress(apiUrl, tile.id, team);
                if (resp != null) {
                    boolean isBoobytrap = tile.completed && boobyTrapTileIds.contains(tile.id);
                    panel.showTileInfo(resp, desc, isBoobytrap);
                }
            });
        });
        panel.setOnTileInfoClose(() -> {
            selectedTileId = -1;
            panel.hideTileInfo();
        });

        navButton = NavigationButton.builder()
            .tooltip("Maze Race Bingo")
            .icon(buildIcon())
            .priority(5)
            .panel(panel)
            .build();
        clientToolbar.addNavigation(navButton);

        if (client.getGameState() == GameState.LOGGED_IN) {
            executor.execute(this::refreshMazeState);
        }

        pollTask = executor.scheduleAtFixedRate(this::refreshMazeState, 60, 60, TimeUnit.SECONDS);
        versionPollTask = executor.scheduleAtFixedRate(this::checkStateVersion, 10, 10, TimeUnit.SECONDS);
    }

    @Override
    protected void shutDown() {
        if (pollTask != null) {
            pollTask.cancel(false);
        }
        if (versionPollTask != null) {
            versionPollTask.cancel(false);
        }
        if (executor != null) {
            executor.shutdownNow();
        }
        notifOverlay.shutdown();
        clientToolbar.removeNavigation(navButton);
        panel.setOnRefresh(null);
        activeTiles.clear();
        xpSnapshot.clear();
        attackedNpcs.clear();
        creditedKills.clear();
        recentSubmits.clear();
        lastKnownVersion = null;
        lastSeenEventId = 0;
        eventsInitialized = false;
        panel.clear();
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged event) {
        if (event.getGameState() == GameState.LOGGED_IN) {
            lastKnownVersion = null;
            executor.execute(this::refreshMazeState);
            // Don't call snapshotXp() here — stats aren't fully loaded yet when
            // LOGGED_IN fires, so the client returns 0 for unloaded skills. The
            // onStatChanged -1 guard handles initialization safely instead.
        } else if (event.getGameState() == GameState.LOGIN_SCREEN
            || event.getGameState() == GameState.HOPPING) {
            activeTiles.clear();
            xpSnapshot.clear();
            attackedNpcs.clear();
            creditedKills.clear();
            recentSubmits.clear();
            selectedTileId = -1;
            lastKnownVersion = null;
            lastSeenEventId = 0;
            eventsInitialized = false;
            panel.clear();
        }
    }

    // --- XP gain ---

    @Subscribe
    public void onStatChanged(StatChanged event) {
        int key = event.getSkill().ordinal();
        int previous = xpSnapshot.getOrDefault(key, -1);
        if (previous < 0) {
            xpSnapshot.put(key, event.getXp());
            return;
        }

        int gained = event.getXp() - previous;
        xpSnapshot.put(key, event.getXp());
        if (gained <= 0) return;

        String skillName = event.getSkill().getName();
        List<ActiveTile> matches = matchingTiles("xp_gain", cfg -> {
            if (cfg.has("skills") && cfg.get("skills").isJsonArray()) {
                for (com.google.gson.JsonElement el : cfg.getAsJsonArray("skills")) {
                    if (skillName.equalsIgnoreCase(el.getAsString())) return true;
                }
                return false;
            }
            return cfg.has("skill") && skillName.equalsIgnoreCase(cfg.get("skill").getAsString());
        });

        for (ActiveTile tile : matches) {
            submitProgress(tile, gained, skillName);
        }

        if (event.getSkill() == Skill.AGILITY) {
            checkAgilityLap();
        }
    }

    private void checkAgilityLap() {
        if (client.getLocalPlayer() == null) return;
        WorldPoint loc = client.getLocalPlayer().getWorldLocation();
        for (Map.Entry<String, int[][]> entry : COURSE_ENDPOINTS.entrySet()) {
            for (int[] ep : entry.getValue()) {
                if (loc.getX() == ep[0] && loc.getY() == ep[1] && loc.getPlane() == ep[2]) {
                    String courseName = entry.getKey();
                    log.info("Agility lap detected: course='{}'", courseName);
                    List<ActiveTile> matches = matchingTiles("agility_lap",
                        cfg -> courseMatchesTile(cfg, courseName));
                    for (ActiveTile tile : matches) {
                        submitProgress(tile, 1, courseName);
                    }
                    return;
                }
            }
        }
    }

    private static boolean courseMatchesTile(JsonObject cfg, String courseName) {
        if (cfg.has("courses") && cfg.get("courses").isJsonArray()) {
            for (com.google.gson.JsonElement el : cfg.getAsJsonArray("courses")) {
                if (courseName.toLowerCase().contains(el.getAsString().toLowerCase())) return true;
            }
            return false;
        }
        if (!cfg.has("course")) return true;
        return courseName.toLowerCase().contains(cfg.get("course").getAsString().toLowerCase());
    }

    // --- NPC kills & damage ---

    @Subscribe
    public void onHitsplatApplied(HitsplatApplied event) {
        if (!(event.getActor() instanceof NPC)) return;
        if (!event.getHitsplat().isMine()) return;
        NPC npc = (NPC) event.getActor();
        attackedNpcs.put(npc.getIndex(), npc);

        int dmg = event.getHitsplat().getAmount();
        String npcName = cleanNpcName(npc);
        if (dmg > 0 && npcName != null) {
            List<ActiveTile> matches = matchingTiles("npc_damage", cfg -> npcMatches(cfg, npcName));
            for (ActiveTile tile : matches) {
                submitProgress(tile, dmg, npcName);
            }
        }
    }

    // NPC names can carry colour tags (e.g. "<col=00ffff>Unstable ice</col>"), which would never
    // equal the plain name a tile is configured with.
    private static String cleanNpcName(NPC npc) {
        String name = npc.getName();
        return name == null ? null : Text.removeTags(name);
    }

    private static boolean npcMatches(JsonObject cfg, String npcName) {
        if (cfg.has("npcs") && cfg.get("npcs").isJsonArray()) {
            for (com.google.gson.JsonElement el : cfg.getAsJsonArray("npcs")) {
                if (npcName.equalsIgnoreCase(el.getAsString())) return true;
            }
            return false;
        }
        return cfg.has("npc") && npcName.equalsIgnoreCase(cfg.get("npc").getAsString());
    }

    @Subscribe
    public void onGameTick(GameTick event) {
        int tick = client.getTickCount();
        recentSubmits.entrySet().removeIf(e -> tick - e.getValue() > 1);
        creditedKills.entrySet().removeIf(e -> tick - e.getValue() > KILL_CREDIT_TICKS);
        checkDeadNpcs();
    }

    // Primary kill signal: fires the moment the death animation starts, before any despawn.
    @Subscribe
    public void onActorDeath(ActorDeath event) {
        if (!(event.getActor() instanceof NPC)) return;
        NPC npc = (NPC) event.getActor();
        if (!attackedNpcs.containsKey(npc.getIndex())) return;
        creditKill(npc, "death");
    }

    // Fallback for NPCs whose ActorDeath was missed (e.g. the plugin started mid-fight).
    private void checkDeadNpcs() {
        for (NPC npc : new ArrayList<>(attackedNpcs.values())) {
            if (npc.isDead()) creditKill(npc, "dead-flag");
        }
    }

    @Subscribe
    public void onNpcDespawned(NpcDespawned event) {
        NPC npc = event.getNpc();
        // Bosses that vanish on the same tick they die never leave a dead NPC behind for the
        // per-tick poll to see, so credit here before dropping the entry.
        if (npc.isDead() && attackedNpcs.containsKey(npc.getIndex())) {
            creditKill(npc, "despawn");
        }
        attackedNpcs.remove(npc.getIndex());
    }

    // Last-resort kill signal for bosses that produce no observable death or despawn state:
    // receiving their loot means they died.
    private void creditKillFromLoot(NPC npc) {
        if (npc == null) return;
        creditKill(npc, "loot");
    }

    private void creditKill(NPC npc, String source) {
        int index = npc.getIndex();
        if (creditedKills.containsKey(index)) return;
        String npcName = cleanNpcName(npc);
        if (npcName == null) return;
        creditedKills.put(index, client.getTickCount());
        attackedNpcs.remove(index);

        log.info("Kill detected via {}: npcName='{}'", source, npcName);
        List<ActiveTile> matches = matchingTiles("npc_kill", cfg -> npcMatches(cfg, npcName));
        log.info("Matched {} tile(s) for npc_kill '{}'", matches.size(), npcName);
        if (matches.isEmpty()) {
            // Tile may have just been revealed but not yet loaded — refresh and retry once
            executor.execute(() -> {
                refreshMazeState();
                List<ActiveTile> retry = matchingTiles("npc_kill", cfg -> npcMatches(cfg, npcName));
                log.info("Retry matched {} tile(s) for npc_kill '{}'", retry.size(), npcName);
                for (ActiveTile tile : retry) {
                    submitProgress(tile, 1, npcName);
                }
            });
        } else {
            for (ActiveTile tile : matches) {
                submitProgress(tile, 1, npcName);
            }
        }
    }

    // --- Agility laps, minigame completions & clue scrolls ---

    // Matches the OSRS reward casket message, e.g. "You have completed 87 hard Treasure Trails."
    private static final java.util.regex.Pattern CLUE_TIER_PATTERN =
        java.util.regex.Pattern.compile("completed [\\d,]+ (\\w+) treasure trails?", java.util.regex.Pattern.CASE_INSENSITIVE);

    @Subscribe
    public void onChatMessage(ChatMessage event) {
        ChatMessageType type = event.getType();
        if (type != ChatMessageType.SPAM && type != ChatMessageType.GAMEMESSAGE) return;

        String msg = event.getMessage().replaceAll("<[^>]*>", "");

        List<ActiveTile> minigameMatches = matchingTiles("minigame_completion", cfg -> {
            if (!cfg.has("message")) return false;
            return msg.toLowerCase().contains(cfg.get("message").getAsString().toLowerCase());
        });
        for (ActiveTile tile : minigameMatches) {
            String minigameName = tile.taskConfig.has("minigame")
                ? tile.taskConfig.get("minigame").getAsString() : null;
            submitProgress(tile, 1, minigameName);
        }

        java.util.regex.Matcher clueMatcher = CLUE_TIER_PATTERN.matcher(msg);
        if (clueMatcher.find()) {
            String tier = clueMatcher.group(1);
            List<ActiveTile> clueMatches = matchingTiles("clue_completion", cfg -> tierMatches(cfg, tier));
            for (ActiveTile tile : clueMatches) {
                submitProgress(tile, 1, tier);
            }
        }
    }

    private static boolean tierMatches(JsonObject cfg, String tier) {
        if (cfg.has("tiers") && cfg.get("tiers").isJsonArray()) {
            for (com.google.gson.JsonElement el : cfg.getAsJsonArray("tiers")) {
                if (tier.equalsIgnoreCase(el.getAsString())) return true;
            }
            return false;
        }
        return cfg.has("tier") && tier.equalsIgnoreCase(cfg.get("tier").getAsString());
    }

    // --- Item drops / chest loot ---

    @Subscribe
    public void onNpcLootReceived(NpcLootReceived event) {
        creditKillFromLoot(event.getNpc());
        for (ItemStack stack : event.getItems()) {
            String itemName = itemManager.getItemComposition(stack.getId()).getName();
            List<ActiveTile> matches = matchingTiles("item_drop", cfg -> {
                if (cfg.has("items") && cfg.get("items").isJsonArray()) {
                    for (com.google.gson.JsonElement el : cfg.getAsJsonArray("items")) {
                        if (itemName.equalsIgnoreCase(el.getAsString())) return true;
                    }
                    return false;
                }
                return cfg.has("item") && itemName.equalsIgnoreCase(cfg.get("item").getAsString());
            });
            for (ActiveTile tile : matches) {
                submitProgress(tile, stack.getQuantity(), itemName);
            }
        }
        submitGpValue(event.getItems());
    }

    @Subscribe
    public void onLootReceived(LootReceived event) {
        for (ItemStack stack : event.getItems()) {
            String itemName = itemManager.getItemComposition(stack.getId()).getName();
            List<ActiveTile> matches = matchingTiles("item_drop", cfg -> {
                if (cfg.has("items") && cfg.get("items").isJsonArray()) {
                    for (com.google.gson.JsonElement el : cfg.getAsJsonArray("items")) {
                        if (itemName.equalsIgnoreCase(el.getAsString())) return true;
                    }
                    return false;
                }
                return cfg.has("item") && itemName.equalsIgnoreCase(cfg.get("item").getAsString());
            });
            for (ActiveTile tile : matches) {
                submitProgress(tile, stack.getQuantity(), itemName);
            }
        }
        submitGpValue(event.getItems());
    }

    private void submitGpValue(Collection<ItemStack> items) {
        List<ActiveTile> gpTiles = matchingTiles("gp_value", cfg -> true);
        if (gpTiles.isEmpty()) return;
        int totalGp = 0;
        for (ItemStack stack : items) {
            totalGp += itemManager.getItemPrice(stack.getId()) * stack.getQuantity();
        }
        if (totalGp <= 0) return;
        for (ActiveTile tile : gpTiles) {
            submitProgress(tile, totalGp, "gp");
        }
    }

    // --- Internal helpers ---

    private void submitProgress(ActiveTile tile, int amount, String subCategory) {
        if (client.getLocalPlayer() == null) return;
        String playerName = client.getLocalPlayer().getName();
        if (playerName == null) return;

        String apiUrl = config.apiUrl();
        String team = config.teamName();
        if (team.isEmpty()) return;

        // npc_damage must never be deduped: multi-hit weapons (e.g. twinflame staff) and
        // burn/poison ticks can legitimately land several real hitsplats on the same NPC
        // within one or two ticks, and each one carries damage that must be counted.
        if (!"npc_damage".equals(tile.taskType)) {
            String dedupKey = tile.id + ":" + subCategory;
            int currentTick = client.getTickCount();
            Integer lastTick = recentSubmits.get(dedupKey);
            if (lastTick != null && currentTick - lastTick <= 1) return;
            recentSubmits.put(dedupKey, currentTick);
        }

        executor.execute(() -> {
            ProgressResponse response = apiClient.postProgress(apiUrl, tile.id, playerName, amount, team, subCategory);
            if (response == null) {
                log.warn("Progress submit for tile {} returned null (API error)", tile.id);
                return;
            }

            if (response.error != null) {
                log.warn("Progress submit for tile {} returned error: {}", tile.id, response.error);
                if (config.chatErrorMessages()) {
                    sendChatMessage("<col=ff0000>" + response.error + "</col>");
                }
                refreshMazeState();
                return;
            }

            log.info("Progress tile {}: progress={}/{} completed={}", tile.id, response.progress, response.target, response.completed);

            String suffix = "xp_gain".equals(tile.taskType) ? " xp"
                : "npc_kill".equals(tile.taskType) ? (amount == 1 ? " kill" : " kills")
                : "npc_damage".equals(tile.taskType) ? " damage"
                : "agility_lap".equals(tile.taskType) ? " lap"
                : "minigame_completion".equals(tile.taskType) ? " completion"
                : "clue_completion".equals(tile.taskType) ? (amount == 1 ? " clue" : " clues")
                : "";
            String contrib = amount + (subCategory != null ? " " + subCategory : "") + suffix;
            if (response.contributed && contributionMessageEnabled(tile.taskType)) {
                sendChatMessage("You contributed " + contrib + " to tile " + tile.id + ".");
            }

            if (response.completed && config.chatCompletionMessages()) {
                sendChatMessage("<col=00ff00>You've completed tile " + tile.id + "!</col>");
            }

            if (response.specialEvent != null && response.specialEvent.isJsonObject()) {
                JsonObject se = response.specialEvent.getAsJsonObject();
                if (se.has("message") && config.chatSpecialEventMessages()) {
                    String seMsg = se.get("message").getAsString();
                    String seType = se.has("type") ? se.get("type").getAsString() : "";
                    String seColor = "gameover".equals(seType) ? "ff0000" : "ffcc00";
                    sendChatMessage("<col=" + seColor + ">" + seMsg + "</col>");
                }
            }

            for (int i = 0; i < activeTiles.size(); i++) {
                ActiveTile t = activeTiles.get(i);
                if (t.id == tile.id) {
                    activeTiles.set(i, new ActiveTile(
                        t.id, t.tileIndex, t.taskType, t.taskConfig,
                        response.progress, response.target, t.description));
                    break;
                }
            }
            panel.updateTiles(activeTiles);
            refreshMazeState();
            String v = apiClient.fetchStateVersion(apiUrl, team);
            if (v != null) lastKnownVersion = v;
        });
    }

    private void checkStateVersion() {
        if (client.getGameState() != GameState.LOGGED_IN) return;
        String team = config.teamName();
        if (team.isEmpty()) return;
        String version = apiClient.fetchStateVersion(config.apiUrl(), team);
        if (version == null) return;
        if (lastKnownVersion == null) {
            // First check after startup/login — prime the version without a redundant refresh.
            lastKnownVersion = version;
            return;
        }
        if (!version.equals(lastKnownVersion)) {
            lastKnownVersion = version;
            refreshMazeState();
        }
    }

    private boolean contributionMessageEnabled(String taskType) {
        if (taskType == null) return true;
        switch (taskType) {
            case "xp_gain": return config.chatContributionXp();
            case "npc_kill": return config.chatContributionNpcKill();
            case "npc_damage": return config.chatContributionNpcDamage();
            case "agility_lap": return config.chatContributionAgilityLap();
            case "minigame_completion": return config.chatContributionMinigame();
            case "clue_completion": return config.chatContributionClueCompletion();
            case "item_drop": return config.chatContributionItemDrop();
            case "gp_value": return config.chatContributionGpValue();
            default: return true;
        }
    }

    // Pink [MazeRaceBingo] prefix as native chat markup. Built as a raw string (not via
    // ChatMessageBuilder.append) because append() escapes angle brackets, which would break
    // the <col=..> tags that callers already embed in their messages.
    private static final String CHAT_PREFIX = "<col=ff6ec7>[MazeRaceBingo]</col> ";

    private void sendChatMessage(String message) {
        chatMessageManager.queue(QueuedMessage.builder()
            .type(ChatMessageType.GAMEMESSAGE)
            .runeLiteFormattedMessage(CHAT_PREFIX + message)
            .build());
    }

    void refreshMazeState() {
        String apiUrl = config.apiUrl();
        String team = config.teamName();
        if (team.isEmpty()) {
            panel.setStatus("No team configured");
            return;
        }

        MazeState state = apiClient.fetchMazeState(apiUrl, team);
        if (state == null) {
            panel.setStatus("Disconnected");
            return;
        }

        log.info("Maze state: size={}, tiles={}, gameOver={}", state.size, state.tiles == null ? "null" : state.tiles.size(), state.gameOver);

        if (state.tileDescriptions != null) {
            tileDescriptions = state.tileDescriptions;
        }

        if (state.boobytraps != null && state.size > 0) {
            Set<Integer> ids = new java.util.HashSet<>();
            for (com.mazebingo.model.MazeState.BoobyTrapPos b : state.boobytraps) {
                ids.add(b.row * state.size + b.col + 1);
            }
            boobyTrapTileIds = ids;
        }

        Set<Integer> revealed = MazeRevealCalculator.computeRevealed(state);
        log.info("Revealed indices: {}", revealed);

        List<ActiveTile> newActive = new ArrayList<>();
        for (int i = 0; i < state.tiles.size(); i++) {
            TileData t = state.tiles.get(i);
            if (t == null) { log.info("Tile at index {} is null", i); continue; }
            if (t.completed) continue;
            if (!revealed.contains(i)) continue;
            if (t.taskType == null) { log.info("Tile {} (index {}) skipped: taskType is null", t.id, i); continue; }
            log.info("Adding tile {} (index {}), taskType={}", t.id, i, t.taskType);

            String desc = "";
            if (state.tileDescriptions != null) {
                desc = state.tileDescriptions.getOrDefault(String.valueOf(t.id), "");
            }

            int req = t.completionsRequired > 0 ? t.completionsRequired : 1;
            JsonObject cfg = (t.taskConfig != null && t.taskConfig.isJsonObject())
                ? t.taskConfig.getAsJsonObject() : null;
            newActive.add(new ActiveTile(t.id, i, t.taskType, cfg,
                t.completionsDone, req, desc));
        }

        activeTiles.clear();
        activeTiles.addAll(newActive);
        panel.setStatus("Connected");
        panel.updateMazeState(state);
        panel.updateTiles(activeTiles);

        if (state.recentEvents != null) {
            if (!eventsInitialized) {
                for (com.mazebingo.model.MazeEventEntry e : state.recentEvents) {
                    if (e.id > lastSeenEventId) lastSeenEventId = e.id;
                }
                eventsInitialized = true;
            } else {
                for (com.mazebingo.model.MazeEventEntry e : state.recentEvents) {
                    if (e.id > lastSeenEventId) {
                        Color color = "tile_complete".equals(e.type) ? Color.WHITE
                            : "keys_missing".equals(e.type) ? Color.RED
                            : "gameover".equals(e.type) ? new Color(76, 175, 80)
                            : new Color(255, 204, 0);
                        panel.addEvent(e.message, color);
                        boolean showPopup = !"tile_complete".equals(e.type) || config.tileCompletionPopupEnabled();
                        notifOverlay.addNotification(e, color, showPopup);
                        lastSeenEventId = e.id;
                    }
                }
            }
        }

        int selId = selectedTileId;
        if (selId >= 0) {
            String desc = tileDescriptions.getOrDefault(String.valueOf(selId), "");
            TileData selTile = state.tiles.stream().filter(t -> t.id == selId).findFirst().orElse(null);
            boolean isBoobytrap = selTile != null && selTile.completed && boobyTrapTileIds.contains(selId);
            TileProgressResponse resp = apiClient.fetchTileProgress(apiUrl, selId, team);
            if (resp != null) {
                panel.showTileInfo(resp, desc, isBoobytrap);
            }
        }
    }

    private List<ActiveTile> matchingTiles(String taskType, Predicate<JsonObject> configMatcher) {
        return activeTiles.stream()
            .filter(t -> taskType.equals(t.taskType))
            .filter(t -> t.taskConfig != null && configMatcher.test(t.taskConfig))
            .collect(Collectors.toList());
    }

    @Provides
    MazeBingoConfig provideConfig(ConfigManager configManager) {
        return configManager.getConfig(MazeBingoConfig.class);
    }

    private static BufferedImage buildIcon() {
        BufferedImage icon = new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = icon.createGraphics();
        g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
        g.setColor(new Color(76, 175, 80));
        g.fillRoundRect(0, 0, 15, 15, 4, 4);
        g.setColor(Color.WHITE);
        g.setFont(new Font(Font.SANS_SERIF, Font.BOLD, 8));
        g.drawString("MB", 2, 11);
        g.dispose();
        return icon;
    }
}

package com.mazebingo;

import com.mazebingo.model.MazeState;
import com.mazebingo.model.TileData;
import com.mazebingo.model.TileProgressResponse;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;

import javax.inject.Inject;
import javax.swing.*;
import javax.swing.border.EmptyBorder;
import java.awt.*;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.List;
import java.util.Set;
import java.util.function.Consumer;

public class MazeBingoPanel extends PluginPanel {

    private static final int MAX_EVENTS = 8;
    /** A task row's own left/right border (6px each), plus a small margin so text never touches the edge. */
    private static final int ROW_HORIZONTAL_PADDING = 16;

    private final JLabel statusLabel;
    private final JPanel tilesPanel;
    private final MazeMapPanel mazeMapPanel;
    private final TileInfoPanel tileInfoPanel;
    private final JPanel eventFeedPanel;
    private final Deque<String[]> recentEvents = new ArrayDeque<>();
    private Runnable onRefresh;

    @Inject
    MazeBingoPanel() {
        setLayout(new BorderLayout(0, 6));
        setBorder(new EmptyBorder(10, 10, 10, 10));
        setBackground(ColorScheme.DARK_GRAY_COLOR);

        JLabel title = new JLabel("Maze Race Bingo");
        title.setFont(FontManager.getRunescapeBoldFont());
        title.setForeground(Color.WHITE);

        statusLabel = new JLabel("● Not connected");
        statusLabel.setFont(FontManager.getRunescapeSmallFont());
        statusLabel.setForeground(Color.RED);

        JButton refreshButton = new JButton("Refresh");
        refreshButton.setFont(FontManager.getRunescapeSmallFont());
        refreshButton.setFocusPainted(false);
        refreshButton.addActionListener(e -> {
            if (onRefresh != null) onRefresh.run();
        });

        JPanel topRow = new JPanel(new BorderLayout(6, 0));
        topRow.setBackground(ColorScheme.DARK_GRAY_COLOR);
        topRow.add(title, BorderLayout.CENTER);
        topRow.add(refreshButton, BorderLayout.EAST);

        JPanel headerPanel = new JPanel(new BorderLayout(0, 2));
        headerPanel.setBackground(ColorScheme.DARK_GRAY_COLOR);
        headerPanel.setBorder(new EmptyBorder(0, 0, 6, 0));
        headerPanel.setAlignmentX(Component.LEFT_ALIGNMENT);
        headerPanel.add(topRow, BorderLayout.NORTH);
        headerPanel.add(statusLabel, BorderLayout.SOUTH);

        mazeMapPanel = new MazeMapPanel();
        tileInfoPanel = new TileInfoPanel();

        tilesPanel = new JPanel();
        tilesPanel.setLayout(new BoxLayout(tilesPanel, BoxLayout.Y_AXIS));
        tilesPanel.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        tilesPanel.setAlignmentX(Component.LEFT_ALIGNMENT);
        tilesPanel.setBorder(BorderFactory.createTitledBorder(
            BorderFactory.createLineBorder(ColorScheme.MEDIUM_GRAY_COLOR), "Active Tasks"));

        eventFeedPanel = new JPanel();
        eventFeedPanel.setLayout(new BoxLayout(eventFeedPanel, BoxLayout.Y_AXIS));
        eventFeedPanel.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        eventFeedPanel.setAlignmentX(Component.LEFT_ALIGNMENT);
        eventFeedPanel.setBorder(BorderFactory.createTitledBorder(
            BorderFactory.createLineBorder(ColorScheme.MEDIUM_GRAY_COLOR), "Recent Events"));

        JPanel content = new JPanel();
        content.setLayout(new BoxLayout(content, BoxLayout.Y_AXIS));
        content.setBackground(ColorScheme.DARK_GRAY_COLOR);
        content.add(headerPanel);
        content.add(mazeMapPanel);
        content.add(Box.createRigidArea(new Dimension(0, 6)));
        content.add(tileInfoPanel);
        content.add(tilesPanel);
        content.add(Box.createRigidArea(new Dimension(0, 6)));
        content.add(eventFeedPanel);

        add(content, BorderLayout.NORTH);
    }

    void updateMazeState(MazeState state) {
        if (state != null) {
            Set<Integer> revealed = MazeRevealCalculator.computeRevealed(state);
            SwingUtilities.invokeLater(() -> mazeMapPanel.updateState(state, revealed));
        }
    }

    void setOnRefresh(Runnable callback) {
        this.onRefresh = callback;
    }

    void setOnTileClick(Consumer<TileData> callback) {
        mazeMapPanel.setOnTileClick(callback);
    }

    void showTileInfoLoading(int tileId, String description) {
        SwingUtilities.invokeLater(() -> tileInfoPanel.showLoading(tileId, description));
    }

    void showTileInfo(TileProgressResponse data, String description, boolean isBoobytrap) {
        SwingUtilities.invokeLater(() -> tileInfoPanel.showTile(data, description, isBoobytrap));
    }

    void setSelectedTileOnMap(int tileId) {
        SwingUtilities.invokeLater(() -> mazeMapPanel.setSelectedTileId(tileId));
    }

    void hideTileInfo() {
        SwingUtilities.invokeLater(() -> {
            tileInfoPanel.clear();
            mazeMapPanel.setSelectedTileId(-1);
        });
    }

    void setOnTileInfoClose(Runnable callback) {
        tileInfoPanel.setOnClose(callback);
    }

    void setStatus(String message) {
        SwingUtilities.invokeLater(() -> {
            boolean connected = "Connected".equals(message);
            statusLabel.setText("● " + message);
            statusLabel.setForeground(connected ? new Color(76, 175, 80) : Color.RED);
        });
    }

    void updateTiles(List<ActiveTile> tiles) {
        SwingUtilities.invokeLater(() -> {
            tilesPanel.removeAll();
            if (tiles.isEmpty()) {
                JLabel empty = new JLabel("No active tasks");
                empty.setForeground(Color.GRAY);
                empty.setFont(FontManager.getRunescapeSmallFont());
                empty.setBorder(new EmptyBorder(6, 6, 6, 6));
                tilesPanel.add(empty);
            } else {
                for (ActiveTile tile : tiles) {
                    tilesPanel.add(buildTileRow(tile));
                    tilesPanel.add(Box.createRigidArea(new Dimension(0, 2)));
                }
            }
            tilesPanel.revalidate();
            tilesPanel.repaint();
        });
    }

    void addEvent(String message, Color color) {
        SwingUtilities.invokeLater(() -> {
            String hex = String.format("%02x%02x%02x", color.getRed(), color.getGreen(), color.getBlue());
            if (recentEvents.size() >= MAX_EVENTS) recentEvents.pollFirst();
            recentEvents.addLast(new String[]{message, hex});
            rebuildEventFeed();
        });
    }

    private void rebuildEventFeed() {
        eventFeedPanel.removeAll();
        if (recentEvents.isEmpty()) {
            JLabel empty = new JLabel("No events yet");
            empty.setForeground(Color.GRAY);
            empty.setFont(FontManager.getRunescapeSmallFont());
            empty.setBorder(new EmptyBorder(4, 6, 4, 6));
            eventFeedPanel.add(empty);
        } else {
            for (String[] entry : recentEvents) {
                JLabel lbl = new JLabel();
                lbl.setForeground(Color.decode("#" + entry[1]));
                lbl.setFont(FontManager.getRunescapeSmallFont());
                lbl.setText(wrapHtml(entry[0], lbl, rowTextWidth(eventFeedPanel)));
                lbl.setToolTipText(entry[0]);
                lbl.setBorder(new EmptyBorder(2, 6, 2, 6));
                eventFeedPanel.add(lbl);
            }
        }
        eventFeedPanel.revalidate();
        eventFeedPanel.repaint();
    }

    void clear() {
        SwingUtilities.invokeLater(() -> {
            tilesPanel.removeAll();
            tilesPanel.revalidate();
            tilesPanel.repaint();
            tileInfoPanel.clear();
            mazeMapPanel.setSelectedTileId(-1);
            recentEvents.clear();
            rebuildEventFeed();
            statusLabel.setText("● Not connected");
            statusLabel.setForeground(Color.RED);
        });
    }

    private JPanel buildTileRow(ActiveTile tile) {
        JPanel row = new JPanel(new BorderLayout(0, 3));
        row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        row.setBorder(new EmptyBorder(5, 6, 5, 6));

        String name = "Tile " + tile.id + ": " + tile.description;
        JLabel nameLabel = new JLabel();
        nameLabel.setForeground(Color.WHITE);
        nameLabel.setFont(FontManager.getRunescapeSmallFont());
        nameLabel.setText(wrapHtml(name, nameLabel, rowTextWidth(tilesPanel)));
        nameLabel.setToolTipText(name);

        int req = tile.completionsRequired > 0 ? tile.completionsRequired : 1;
        int pct = (int) Math.min(100.0, (tile.completionsDone * 100.0) / req);

        String progress = progressString(tile);
        JProgressBar bar = new JProgressBar(0, 100);
        bar.setValue(pct);
        bar.setStringPainted(true);
        bar.setString(progress);
        bar.setFont(FontManager.getRunescapeSmallFont());
        bar.setToolTipText(progress);
        bar.setForeground(new Color(76, 175, 80));
        bar.setBackground(ColorScheme.MEDIUM_GRAY_COLOR);
        bar.setPreferredSize(new Dimension(0, 16));

        row.add(nameLabel, BorderLayout.NORTH);
        row.add(bar, BorderLayout.SOUTH);
        // Height must follow the (possibly multi-line) label, or BoxLayout clips the wrapped text.
        row.setMaximumSize(new Dimension(Integer.MAX_VALUE, row.getPreferredSize().height));
        return row;
    }

    /**
     * Width available for the text of a row inside {@code container}: the side panel minus this panel's
     * border, the container's titled border and the row's own padding. Derived from this panel rather than
     * from the container, whose width is meaningless until it holds a full-width row.
     */
    private int rowTextWidth(JPanel container) {
        int width = getWidth() > 0 ? getWidth() : PluginPanel.PANEL_WIDTH;
        Insets panelInsets = getInsets();
        Insets containerInsets = container.getInsets();
        return Math.max(80, width - panelInsets.left - panelInsets.right
            - containerInsets.left - containerInsets.right - ROW_HORIZONTAL_PADDING);
    }

    /**
     * Renders {@code text} as HTML broken into lines that fit {@code maxWidth} in {@code label}'s font.
     * The breaks have to be measured here: a CSS {@code width} only hints at where Swing's HTML view
     * should wrap, and it lays out wider than asked, which clips long task names at the panel's edge.
     */
    private static String wrapHtml(String text, JLabel label, int maxWidth) {
        FontMetrics metrics = label.getFontMetrics(label.getFont());
        List<String> lines = new ArrayList<>();
        StringBuilder line = new StringBuilder();
        for (String word : text.trim().split("\\s+")) {
            if (line.length() > 0 && metrics.stringWidth(line + " " + word) > maxWidth) {
                lines.add(line.toString());
                line.setLength(0);
            }
            if (line.length() > 0) {
                line.append(' ');
            }
            // A word too long for a line of its own (a pasted item name, say) is split mid-word.
            while (word.length() > 1 && metrics.stringWidth(line + word) > maxWidth) {
                int fit = word.length();
                while (fit > 1 && metrics.stringWidth(line + word.substring(0, fit)) > maxWidth) {
                    fit--;
                }
                lines.add(line.toString() + word.substring(0, fit));
                line.setLength(0);
                word = word.substring(fit);
            }
            line.append(word);
        }
        if (line.length() > 0) {
            lines.add(line.toString());
        }

        StringBuilder html = new StringBuilder("<html>");
        for (int i = 0; i < lines.size(); i++) {
            if (i > 0) {
                html.append("<br>");
            }
            html.append(escapeHtml(lines.get(i)));
        }
        return html.append("</html>").toString();
    }

    private static String escapeHtml(String text) {
        return text.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
    }

    private String progressString(ActiveTile tile) {
        int req = tile.completionsRequired > 0 ? tile.completionsRequired : 1;
        if ("xp_gain".equals(tile.taskType)) {
            return String.format("%,d / %,d xp", tile.completionsDone, req);
        }
        if ("npc_damage".equals(tile.taskType)) {
            return String.format("%,d / %,d damage", tile.completionsDone, req);
        }
        return String.format("%,d / %,d", tile.completionsDone, req);
    }
}

package com.mazebingo;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import com.mazebingo.model.MazeState;
import com.mazebingo.model.ProgressResponse;
import com.mazebingo.model.TileProgressResponse;
import okhttp3.*;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import javax.inject.Inject;
import javax.inject.Singleton;

@Singleton
public class MazeApiClient {

    private static final Logger log = LoggerFactory.getLogger(MazeApiClient.class);

    private static final MediaType JSON_MEDIA_TYPE = MediaType.parse("application/json; charset=utf-8");

    @Inject
    private OkHttpClient httpClient;

    @Inject
    private Gson gson;

    public MazeState fetchMazeState(String apiUrl, String team) {
        HttpUrl url = HttpUrl.parse(apiUrl + "/api/maze")
            .newBuilder()
            .addQueryParameter("team", team)
            .build();

        Request request = new Request.Builder().url(url).get().build();
        try (Response response = httpClient.newCall(request).execute()) {
            if (!response.isSuccessful() || response.body() == null) {
                log.warn("Maze API returned {}", response.code());
                return null;
            }
            return gson.fromJson(response.body().charStream(), MazeState.class);
        } catch (Exception e) {
            log.warn("Failed to fetch maze state", e);
            return null;
        }
    }

    public ProgressResponse postProgress(String apiUrl, int tileId, String playerName, int amount, String team, String subCategory) {
        HttpUrl url = HttpUrl.parse(apiUrl + "/api/tiles/progress/" + tileId)
            .newBuilder()
            .addQueryParameter("team", team)
            .build();

        JsonObject body = new JsonObject();
        body.addProperty("playerName", playerName);
        body.addProperty("amount", amount);
        if (subCategory != null) {
            body.addProperty("subCategory", subCategory);
        }

        RequestBody requestBody = RequestBody.create(JSON_MEDIA_TYPE, gson.toJson(body));

        // A 5xx is treated as transient and retried once so a brief server-side hiccup
        // doesn't silently drop this contribution (there's no other retry path for it).
        for (int attempt = 1; attempt <= 2; attempt++) {
            Request request = new Request.Builder().url(url).post(requestBody).build();
            try (Response response = httpClient.newCall(request).execute()) {
                if (response.code() >= 500 && attempt == 1) {
                    log.warn("Progress POST for tile {} returned {}, retrying once", tileId, response.code());
                    continue;
                }
                if (response.body() == null) {
                    log.warn("Progress POST for tile {} returned {} with no body", tileId, response.code());
                    return null;
                }
                ProgressResponse result = gson.fromJson(response.body().charStream(), ProgressResponse.class);
                if (!response.isSuccessful()) {
                    log.warn("Progress POST for tile {} returned {}", tileId, response.code());
                }
                return result;
            } catch (Exception e) {
                log.warn("Failed to post progress for tile {}", tileId, e);
                return null;
            }
        }
        return null;
    }

    public String fetchStateVersion(String apiUrl, String team) {
        HttpUrl url = HttpUrl.parse(apiUrl + "/api/state-version")
            .newBuilder()
            .addQueryParameter("team", team)
            .build();

        Request request = new Request.Builder().url(url).get().build();
        try (Response response = httpClient.newCall(request).execute()) {
            if (!response.isSuccessful() || response.body() == null) return null;
            JsonObject obj = gson.fromJson(response.body().charStream(), JsonObject.class);
            return obj.has("lastUpdated") && !obj.get("lastUpdated").isJsonNull()
                ? obj.get("lastUpdated").getAsString() : null;
        } catch (Exception e) {
            log.warn("Failed to fetch state version", e);
            return null;
        }
    }

    public TileProgressResponse fetchTileProgress(String apiUrl, int tileId, String team) {
        HttpUrl url = HttpUrl.parse(apiUrl + "/api/tiles/progress/" + tileId)
            .newBuilder()
            .addQueryParameter("team", team)
            .build();

        Request request = new Request.Builder().url(url).get().build();
        try (Response response = httpClient.newCall(request).execute()) {
            if (!response.isSuccessful() || response.body() == null) {
                log.warn("Tile progress GET for tile {} returned {}", tileId, response.code());
                return null;
            }
            return gson.fromJson(response.body().charStream(), TileProgressResponse.class);
        } catch (Exception e) {
            log.warn("Failed to fetch tile progress for tile {}", tileId, e);
            return null;
        }
    }
}

